//! The entry point: opens a provider stream and turns it into response events.
//!
//! This is the drop-in replacement for
//! `warp_multi_agent_client::generate_multi_agent_output`. The signature is the same shape, less
//! the server client, because nothing here needs an access token.

use std::collections::VecDeque;

use futures::{StreamExt, stream};
use reqwest_eventsource::{Event, EventSource, RequestBuilderExt};
use warp_multi_agent_api as api;

use crate::config::Schema;
use crate::emit::Emitter;
use crate::mcp::McpCatalog;
use crate::provider::{Delta, StopReason};
use crate::{Error, OutputStream, config, convert, prompt, provider, tools};

/// Sends one agent request to the user's own provider, and streams the reply back as the
/// response events that the client applies.
pub async fn generate_local_output(request: &api::Request) -> Result<OutputStream, Error> {
    let target = config::resolve_target(request)?;
    let turns = convert::turns_from_request(request);
    if turns.is_empty() {
        return Err(Error::NoInput);
    }

    let supported_tools = request
        .settings
        .as_ref()
        .map(|settings| settings.supported_tools.clone())
        .unwrap_or_default();
    let mut tool_schemas = tools::schemas_for(&supported_tools);
    tool_schemas.extend(McpCatalog::from_request(request).schemas(&supported_tools));

    let body = provider::build_body(
        &target,
        &prompt::system_prompt(request),
        &turns,
        &tool_schemas,
    );

    let mut builder = reqwest::Client::new()
        .post(target.endpoint_url())
        .header("content-type", "application/json")
        .json(&body);
    for (name, value) in provider::headers(&target) {
        builder = builder.header(name, value);
    }

    let source = builder
        .eventsource()
        .map_err(|error| Error::ProviderStatus {
            status: 0,
            body: error.to_string(),
        })?;

    let mut emitter = Emitter::new(request);
    let opening = emitter.start();

    let state = State {
        source,
        emitter,
        schema: target.schema,
        queue: opening.into(),
        stop: None,
        done: false,
    };

    Ok(stream::unfold(state, next_event).boxed())
}

struct State {
    source: EventSource,
    emitter: Emitter,
    schema: Schema,
    /// Events that are ready to hand to the client.
    queue: VecDeque<api::ResponseEvent>,
    /// The stop reason from the provider, kept until the stream closes.
    stop: Option<StopReason>,
    done: bool,
}

/// Pulls the next event, reading more of the provider stream when the queue runs dry.
async fn next_event(mut state: State) -> Option<(Result<api::ResponseEvent, Error>, State)> {
    loop {
        if let Some(event) = state.queue.pop_front() {
            return Some((Ok(event), state));
        }
        if state.done {
            return None;
        }

        match state.source.next().await {
            Some(Ok(Event::Open)) => continue,
            Some(Ok(Event::Message(message))) => {
                for delta in provider::parse_event(state.schema, &message.event, &message.data) {
                    match delta {
                        Delta::Stop(reason) => state.stop = Some(reason),
                        Delta::Error { code, message } => {
                            state.done = true;
                            return Some((Err(Error::ProviderStream { code, message }), state));
                        }
                        delta => state.queue.extend(state.emitter.on_delta(delta)),
                    }
                }
            }
            // A closed stream is the normal end of a reply. The provider sent its stop reason
            // just before, so the reply is finished with that reason.
            Some(Err(reqwest_eventsource::Error::StreamEnded)) | None => {
                let reason = state.stop.unwrap_or(StopReason::EndTurn);
                state.queue.extend(state.emitter.finish(reason));
                state.done = true;
            }
            Some(Err(reqwest_eventsource::Error::InvalidStatusCode(status, response))) => {
                let body = response.text().await.unwrap_or_default();
                state.done = true;
                return Some((
                    Err(Error::ProviderStatus {
                        status: status.as_u16(),
                        body,
                    }),
                    state,
                ));
            }
            Some(Err(error)) => {
                state.done = true;
                return Some((Err(Error::EventSource(Box::new(error))), state));
            }
        }
    }
}
//! The OpenAI Chat Completions API.
//!
//! This schema also covers OpenRouter, Google's OpenAI-compatible endpoint, and local servers
//! such as Ollama, LM Studio, and vLLM, so it is the fallback for any custom endpoint.
//!
//! Reference shape of a streaming reply:
//!
//! ```text
//! data: {"choices":[{"delta":{"content":"Hello"}}]}
//! data: {"choices":[{"delta":{"tool_calls":[{"index":0,"id":"call_1",
//!        "function":{"name":"grep","arguments":"{\"queries\""}}]}}]}
//! data: {"choices":[{"delta":{},"finish_reason":"tool_calls"}]}
//! data: {"choices":[],"usage":{"prompt_tokens":812,"completion_tokens":40}}
//! data: [DONE]
//! ```

use serde_json::{Value, json};

use crate::config::ProviderTarget;
use crate::convert::Turn;
use crate::provider::{Delta, StopReason, TokenUsage};
use crate::tools::ToolSchema;

pub fn headers(target: &ProviderTarget) -> Vec<(&'static str, String)> {
    vec![("authorization", format!("Bearer {}", target.api_key))]
}

pub fn build_body(
    target: &ProviderTarget,
    system_prompt: &str,
    turns: &[Turn],
    tools: &[ToolSchema],
) -> Value {
    let mut messages = vec![json!({ "role": "system", "content": system_prompt })];
    for turn in turns {
        push_messages(&mut messages, turn, target.is_custom);
    }

    let tools = tools
        .iter()
        .map(|tool| {
            json!({
                "type": "function",
                "function": {
                    "name": tool.name,
                    "description": tool.description,
                    "parameters": tool.input_schema,
                },
            })
        })
        .collect::<Vec<_>>();

    let mut body = json!({
        "model": target.model,
        "stream": true,
        "stream_options": { "include_usage": true },
        "messages": messages,
    });
    if !tools.is_empty() {
        body["tools"] = Value::Array(tools);
    }
    body
}

fn push_messages(messages: &mut Vec<Value>, turn: &Turn, is_custom: bool) {
    match turn {
        Turn::User(text) => messages.push(json!({ "role": "user", "content": text })),
        Turn::Assistant {
            text,
            reasoning,
            tool_calls,
        } => {
            let mut message = json!({ "role": "assistant" });
            // The API rejects an assistant message with neither content nor tool calls, so an
            // empty text still goes out as an explicit null when tool calls are present.
            message["content"] = if text.is_empty() {
                Value::Null
            } else {
                Value::String(text.clone())
            };
            if !tool_calls.is_empty() {
                message["tool_calls"] = Value::Array(
                    tool_calls
                        .iter()
                        .map(|call| {
                            json!({
                                "id": call.id,
                                "type": "function",
                                "function": {
                                    "name": call.name,
                                    // The API takes the arguments as a JSON string, not an object.
                                    "arguments": call.arguments.to_string(),
                                },
                            })
                        })
                        .collect(),
                );
                // A reasoning model in thinking mode can refuse a conversation where an assistant
                // message that called a tool arrives without the thinking that led to the call.
                // DeepSeek behind a LiteLLM gateway answers 400 with
                // "`reasoning_content` in the thinking mode must be passed back to the API".
                //
                // The field only has to be present: an empty string is accepted, so a reply that
                // streamed no thinking still round-trips. It is sent to custom endpoints only,
                // because it is outside the official schema and a first-party provider may
                // reject an unknown message field.
                if is_custom {
                    message["reasoning_content"] = Value::String(reasoning.clone());
                }
            }
            messages.push(message);
        }
        // Each tool result is its own message, unlike Anthropic, which groups them.
        Turn::ToolResults(results) => {
            for result in results {
                messages.push(json!({
                    "role": "tool",
                    "tool_call_id": result.id,
                    "content": result.content,
                }));
            }
        }
    }
}

pub fn parse_event(data: &str) -> Vec<Delta> {
    if data.trim() == "[DONE]" {
        // The reply already ended with a `finish_reason`. A second stop here would end it twice.
        return Vec::new();
    }
    let Ok(value) = serde_json::from_str::<Value>(data) else {
        return Vec::new();
    };

    let mut deltas = Vec::new();
    // The usage chunk comes last and usually has no choices, but some servers attach `usage` to
    // the chunk that carries the `finish_reason`.
    if let Some(usage) = usage(&value["usage"]) {
        deltas.push(Delta::Usage(usage));
    }

    let Some(choice) = value["choices"]
        .as_array()
        .and_then(|choices| choices.first())
    else {
        return deltas;
    };
    let delta = &choice["delta"];

    if let Some(text) = delta["content"].as_str()
        && !text.is_empty()
    {
        deltas.push(Delta::Text(text.to_string()));
    }

    // Not part of the OpenAI schema, but OpenRouter and several local servers put reasoning here.
    if let Some(text) = delta["reasoning"]
        .as_str()
        .or(delta["reasoning_content"].as_str())
        && !text.is_empty()
    {
        deltas.push(Delta::Reasoning(text.to_string()));
    }

    if let Some(calls) = delta["tool_calls"].as_array() {
        for call in calls {
            let index = call["index"].as_u64().unwrap_or(0) as usize;
            let function = &call["function"];
            // A call opens with an id and a name, then streams its arguments in later events
            // that carry the index alone.
            if let (Some(id), Some(name)) = (call["id"].as_str(), function["name"].as_str()) {
                deltas.push(Delta::ToolCallStart {
                    index,
                    id: id.to_string(),
                    name: name.to_string(),
                });
            }
            if let Some(fragment) = function["arguments"].as_str()
                && !fragment.is_empty()
            {
                deltas.push(Delta::ToolCallArguments {
                    index,
                    fragment: fragment.to_string(),
                });
            }
        }
    }

    if let Some(reason) = choice["finish_reason"].as_str() {
        deltas.push(Delta::Stop(stop_reason(reason)));
    }

    deltas
}

fn usage(usage: &Value) -> Option<TokenUsage> {
    if !usage.is_object() {
        return None;
    }
    let count = |value: &Value| value.as_u64().unwrap_or(0) as u32;
    Some(TokenUsage {
        input: count(&usage["prompt_tokens"]),
        output: count(&usage["completion_tokens"]),
        cache_read: count(&usage["prompt_tokens_details"]["cached_tokens"]),
        cache_write: 0,
    })
}

fn stop_reason(reason: &str) -> StopReason {
    match reason {
        "stop" => StopReason::EndTurn,
        "tool_calls" | "function_call" => StopReason::ToolUse,
        "length" => StopReason::MaxTokens,
        _ => StopReason::Other,
    }
}

